from sklearn.pipeline import make_pipeline
D=pd.read_csv('/data/train.csv.gz'); tr=D.split.eq('train').values; va=~tr; y=D.target.values
AA='ACDEFGHIKLMNPQRSTVWY'; idx={a:i for i,a in enumerate(AA)}
def feats(s):
 x=np.zeros(20+400+5,np.float32); n=len(s)
 for i,a in enumerate(s):
  j=idx.get(a)
  if j is not None:x[j]+=1
  if i+1<n and j is not None:
   k=idx.get(s[i+1])
   if k is not None:x[20+j*20+k]+=1
 x[:20]/=n; x[20:420]/=max(1,n-1)
 x[420:]=[np.log(n),n==512,sum(c in 'FWY' for c in s)/n,sum(c in 'DE' for c in s)/n,sum(c in 'KR' for c in s)/n]
 return x
X=np.array([feats(s) for s in D.sequence])
for model in [Ridge(alpha=10),ExtraTreesRegressor(n_estimators=300,min_samples_leaf=3,max_features=.8,n_jobs=-1),HistGradientBoostingRegressor(max_iter=300,l2_regularization=3,max_leaf_nodes=15)]:
 t=time.time(); model.fit(X[tr],y[tr]); p=model.predict(X[va]);print(type(model).__name__,spearmanr(y[va],p).statistic,'sec',time.time()-t)
for ng in [(1,3),(2,4),(3,5)]:
 t=time.time();v=TfidfVectorizer(analyzer='char',ngram_range=ng,min_df=2,max_features=100000,sublinear_tf=True,dtype=np.float32); xt=v.fit_transform(D.loc[tr,'sequence']); xv=v.transform(D.loc[va,'sequence'])
 for a in [1,10,100]:
  m=Ridge(alpha=a).fit(xt,y[tr]);p=m.predict(xv);print('tfidf',ng,a,xt.shape,spearmanr(y[va],p).statistic,'sec',time.time()-t)
